INSERT OR REPLACE INTO "Volume Growth IN" SELECT coalesce(k0."Brand", error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Channel", error('cells name a member Channel does not have: ' || c."Channel")), coalesce(k2."Versions", error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k3."Years", error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE)
